let currentLanguage='ru';
function setLanguage(language){currentLanguage=Object.hasOwn(copy,language)?language:'en';const text=copy[currentLanguage];document.documentElement.lang=currentLanguage;document.querySelectorAll('[data-i18n]').forEach(el=>{if(text[el.dataset.i18n])el.textContent=text[el.dataset.i18n];});document.getElementById('language').value=currentLanguage;document.title=`Garmin Desk — ${text.heroOne} ${text.heroTwo}`;document.querySelector('meta[name="description"]').content=text.heroDescription;document.querySelector('nav').setAttribute('aria-label',text.navigation);document.querySelector('.theme-switch').setAttribute('aria-label',text.appearance);document.querySelectorAll('.theme-switch button').forEach(button=>button.setAttribute('aria-label',text[button.dataset.theme]));try{localStorage.setItem('garmin-desk-language',currentLanguage)}catch{}}
let initialLanguage='ru';try{initialLanguage=new URLSearchParams(location.search).get('lang')||localStorage.getItem('garmin-desk-language')||navigator.language.split('-')[0]}catch{}setLanguage(initialLanguage);
document.getElementById('language').addEventListener('change',event=>{setLanguage(event.target.value);const url=new URL(location.href);url.searchParams.set('lang',currentLanguage);history.replaceState(null,'',url);});
document.querySelectorAll('.theme-switch button').forEach(button=>button.addEventListener('click',()=>{document.getElementById('showcase').dataset.theme=button.dataset.theme;document.querySelectorAll('.theme-switch button').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));}));
